function match(route,req){
  if(route.method!==req.method)return null;
  var rp=route.path.split('/'),qp=req.path.split('/');
  if(rp.length!==qp.length)return null;
  var params={};
  for(var i=0;i<rp.length;i++){
    if(rp[i][0]===':')params[rp[i].slice(1)]=qp[i];
    else if(rp[i]!==qp[i])return null;}
  return params;}
console.log('Routing '+DATA.requests.length+' requests ('+DATA.label+'):');
DATA.requests.forEach(function(req){
  var hit=null,params=null;
  for(var i=0;i<DATA.routes.length;i++){var m=match(DATA.routes[i],req);
    if(m){hit=DATA.routes[i];params=m;break;}}
  if(hit)console.log('  '+req.method+' '+req.path+' -> '+hit.handler+' '+JSON.stringify(params));
  else console.log('  '+req.method+' '+req.path+' -> 404');});
})();

